mapper.update:
        UPDATE S2C_USER
            SET FAILED_LOGIN_COUNT = FAILED_LOGIN_COUNT + 1,
                USER_STATUS = CASE WHEN FAILED_LOGIN_COUNT + 1 >= #{threshold}
                                THEN 'LOCKED' ELSE USER_STATUS END,
                LOCKED_UNTIL = CASE WHEN FAILED_LOGIN_COUNT + 1 >= #{threshold}
                                THEN SYSTIMESTAMP + NUMTODSINTERVAL(#{lockMinutes}, 'MINUTE')
                                ELSE LOCKED_UNTIL END,
                UPDATED_AT = SYSTIMESTAMP,
                UPDATED_BY = 'AUTH'
        WHERE USER_ID = #{userId}
